export const albumFor = (slug: string) => albums.find((a) => a.slug === slug);
export const albumCover = (a: Album) => a.photos[a.cover];

/** The album's cover as a site CoverImage (the Foundation's own photograph, cleared for its website). */
export function albumCoverImage(slug: string): import("./content").CoverImage | undefined {
  const a = albumFor(slug);
  if (!a) return undefined;
  const p = albumCover(a);
  return { src: p.src, alt: p.caption.en, credit: a.credit, sourceUrl: a.source.url, license: "Syndy Emade Foundation photograph", status: "approved" };
}
